/**
 * English message catalog — the source of truth for every key. `fr.ts`
 * must carry exactly the same key set (enforced by `MessageKey` below
 * and by `scripts/check-i18n-parity.ts`, run in CI/pre-commit once
 * wired — see todo-i18n.md Stage 0).
 *
 * Keys are flat dot-paths, namespaced per module/screen
 * (`common.*` = shared chrome reused everywhere; `auth.*`, `settings.*`,
 * etc. = one screen/module's own strings). Interpolation is a simple
 * `{paramName}` substring replace, not full ICU — plural/gender rules
 * are not handled generically. If a future string genuinely needs real
 * pluralization (e.g. "{n} documents" vs "{n} document"), write both
 * forms as separate keys and pick one in the calling component — don't
 * invent ad hoc ICU syntax inside a value string.
 */
