  'pvCaseDetail.infoCausalityBody1': 'for every suspect product paired with every reported reaction, someone has to judge',
  'pvCaseDetail.infoCausalityBodyEm': 'how likely it is that this specific drug caused this specific reaction',
  'pvCaseDetail.infoCausalityBody2':
    '— not just per case, but per pair, because a case with 2 drugs and 2 reactions needs 4 separate judgments (Drug A might clearly explain the rash while being unrelated to the nausea, for example). Two real pharmacovigilance scoring methods produce that judgment, captured independently:',
  'pvCaseDetail.whoUmcLabel': 'WHO-UMC',
  'pvCaseDetail.infoCausalityWhoUmc':
    '(pick one of 6 categories — Certain, Probable, Possible, Unlikely, and so on — guided by a checklist of what has to be true for each)',
  'pvCaseDetail.andWord': 'and',
  'pvCaseDetail.naranjoLabel': 'Naranjo',
  'pvCaseDetail.infoCausalityNaranjo':
    "(10 yes/no/don't-know questions, auto-totaled into a score from roughly -4 to +13, interpreted as Definite/Probable/Possible/Doubtful). Click a pair below to open its assessment.",
  'pvCaseDetail.sectionConsent': 'Consent',
  'pvCaseDetail.infoConsentWhatThisMeans': 'What this means here:',
  'pvCaseDetail.infoConsentBody1': 'not consent to treatment — consent to',
  'pvCaseDetail.infoConsentBodyEm': 'process and report',
  'pvCaseDetail.infoConsentBody2':
    "this adverse-event information, including sharing it with the regulator (PPB) if required. A case report often contains identifiable health information, so before it's used and forwarded, there should be a record of whether the patient (or whoever reported on their behalf) was asked and agreed. This is a compliance/audit-trail record, not a clinical requirement — the case still exists and can still be processed either way; this just tracks whether permission was sought and what the answer was.",
  'pvCaseDetail.reportConsentLabel': 'Report consent',
  'pvCaseDetail.sectionCaseFollowUp': 'Case Follow-Up',
  'pvCaseDetail.subtitleCaseFollowUp':
    'Checking back with the reporter for missing details or an outcome update — up to two attempts, closing within 28 days',
  'pvCaseDetail.infoFollowUp':
    'Follow-up needs the reporter\'s consent to be contacted (a separate "contact" consent from the report consent above) before an automated email goes out — without it, the system opens the same tracked attempt window but relies on a human calling the reporter and logging what happened. Attempt 1 gets 5 working days to get a response; no response escalates to attempt 2 on the same terms; still nothing closes the case as failed-to-follow-up. Any real reply resets the clock to a fresh 7 days. The whole cycle closes within 28 days of starting, no matter what.',
