  'wasteDisposal.step2Why': 'Apply to the Pharmacy and Poisons Board on the Second Schedule Part A form and pay the KES 2,500 application fee (Second Schedule Part B; r.17(2)). PPB must issue the Certificate of Safe Disposal within 30 days of the application (r.17(3)).',
